import 'dart:async';
import 'dart:convert';
import 'package:http/http.dart' as http;

/// AuraMed Healthcare AI — NASA Space Apps Challenge 2026
/// Unified API Integration Service for Flutter Mobile & Tablet.
class AuraMedApiService {
  // Public HTTPS URL generated by Cloudflare Tunnel
  static String baseUrl = 'https://americans-commit-domestic-mining.trycloudflare.com';

  // API Key configured in AuraMed server (.env)
  static String apiKey = 'auramed-secret-key-2026';

  static Map<String, String> get _headers => {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        'X-API-Key': apiKey,
      };

  /// 1. Health Probe & Mode Monitor (Online / Offline / Local Fallback)
  static Future<Map<String, dynamic>?> checkHealth() async {
    try {
      final response = await http
          .get(Uri.parse('$baseUrl/health'))
          .timeout(const Duration(seconds: 5));
      if (response.statusCode == 200) {
        return jsonDecode(response.body);
      }
    } catch (_) {}
    return null;
  }

  /// 2. Comprehensive Astronaut Vitals Telemetry Assessment
  /// Evaluates anomalies, checks deterministic safety rules, retrieves NASA Tier 1 checklists.
  static Future<Map<String, dynamic>> assessAstronaut({
    required String astronautId,
    required double heartRate,
    required double spo2,
    required double temp,
    required double respiratoryRate,
    required double systolicBp,
    required double diastolicBp,
    required double hrv,
    double? heartRateRollingMean,
    double? spo2RollingMean,
  }) async {
    final payload = {
      'request_id': 'REQ-${DateTime.now().millisecondsSinceEpoch}',
      'astronaut_id': astronautId,
      'vitals': {
        'heart_rate_bpm': heartRate,
        'spo2_percent': spo2,
        'body_temperature_c': temp,
        'respiratory_rate_bpm': respiratoryRate,
        'systolic_bp_mmhg': systolicBp,
        'diastolic_bp_mmhg': diastolicBp,
        'hrv_rmssd_ms': hrv,
        'heart_rate_bpm_rolling_mean_60min': heartRateRollingMean ?? heartRate,
        'heart_rate_bpm_rolling_std_60min': 3.5,
        'spo2_percent_rolling_mean_60min': spo2RollingMean ?? 98.0,
        'spo2_percent_rolling_std_60min': 1.0,
      }
    };

    try {
      final response = await http
          .post(
            Uri.parse('$baseUrl/api/v1/assess-astronaut'),
            headers: _headers,
            body: jsonEncode(payload),
          )
          .timeout(const Duration(seconds: 60));

      if (response.statusCode == 200) {
        return jsonDecode(response.body);
      } else {
        throw Exception('AuraMed API Error (${response.statusCode}): ${response.body}');
      }
    } on TimeoutException {
      throw Exception('Timeout: The local AI engine is taking longer to synthesize the response.');
    } catch (e) {
      throw Exception('Connection error: $e');
    }
  }

  /// 3. Medical RAG Chat & Free-text Clinical Consultation
  static Future<String> chatConsultation(String query) async {
    final response = await http
        .post(
          Uri.parse('$baseUrl/v1/chat'),
          headers: _headers,
          body: jsonEncode({
            'query': query,
            'message': query,
            'history': [],
          }),
        )
        .timeout(const Duration(seconds: 60));

    if (response.statusCode == 200) {
      final data = jsonDecode(response.body);
      return data['summary'] ?? data['response'] ?? '';
    } else {
      throw Exception('Chat API Error: ${response.body}');
    }
  }
}
